const r = await fetch(`${BASE}/movimentos?${params}`, {
  headers: { Authorization: `Bearer ${token}` },
});

if (r.status === 204) return [];                 // sem registros: NAO chamar r.json()
if (r.status === 503) throw new Error("instalacao do cliente fora do ar; repetir com backoff");
if (!r.ok) throw new Error(`HTTP ${r.status}: ${await r.text()}`);
const dados = await r.json();
